import time
import random

class NaiveArray:
    """Implements point updates and range sum queries using a standard array."""
    def __init__(self, data):
        self.arr = list(data)

    def update(self, index, val):
        self.arr[index] = val

    def query(self, left, right):
        return sum(self.arr[left:right + 1])

class SegmentTree:
    """Implements a Segment Tree for O(log N) updates and queries."""
    def __init__(self, data):
        self.n = len(data)
        self.tree = [0] * (4 * self.n)
        self._build(data, 1, 0, self.n - 1)

    def _build(self, data, node, start, end):
        if start == end:
            self.tree[node] = data[start]
            return
        mid = (start + end) // 2
        self._build(data, 2 * node, start, mid)
        self._build(data, 2 * node + 1, mid + 1, end)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def update(self, index, val):
        self._update(1, 0, self.n - 1, index, val)

    def _update(self, node, start, end, idx, val):
        if start == end:
            self.tree[node] = val
            return
        mid = (start + end) // 2
        if idx <= mid:
            self._update(2 * node, start, mid, idx, val)
        else:
            self._update(2 * node + 1, mid + 1, end, idx, val)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def query(self, l, r):
        return self._query(1, 0, self.n - 1, l, r)

    def _query(self, node, start, end, l, r):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        return self._query(2 * node, start, mid, l, r) + \
               self._query(2 * node + 1, mid + 1, end, l, r)

def run_benchmark():
    N = 100000
    Q = 50000
    data = [random.randint(0, 1000) for _ in range(N)]

    # Generate operations: (type, index/left, value/right)
    # type 0: update, type 1: query
    ops = []
    for _ in range(Q):
        op_type = random.choice([0, 1])
        if op_type == 0:
            ops.append((0, random.randint(0, N-1), random.randint(0, 1000)))
        else:
            l = random.randint(0, N-1)
            r = random.randint(l, N-1)
            ops.append((1, l, r))

    print(f"Benchmarking N={N}, Q={Q} operations...\n")

    # Benchmark Naive
    naive = NaiveArray(data)
    start_time = time.time()
    for op in ops:
        if op[0] == 0:
            naive.update(op[1], op[2])
        else:
            _ = naive.query(op[1], op[2])
    naive_time = time.time() - start_time
    print(f"Naive Array Strategy: {naive_time:.4f} seconds")

    # Benchmark Segment Tree
    st = SegmentTree(data)
    start_time = time.time()
    for op in ops:
        if op[0] == 0:
            st.update(op[1], op[2])
        else:
            _ = st.query(op[1], op[2])
    st_time = time.time() - start_time
    print(f"Segment Tree Strategy: {st_time:.4f} seconds")

    print(f"\nSpeedup Factor: {naive_time / st_time:.2f}x")

if __name__ == "__main__":
    run_benchmark()
